Arguments:
$ErrorActionPreference='Stop'
$obj='benchmarks/SomeEngine.ECS.Relations.Benchmarks/obj/Release/net10.0/win-x64/native/SomeEngine.ECS.Relations.Benchmarks.obj'
$llvm='C:\Program Files\LLVM\bin\llvm-objdump.exe'
$info=Get-Item -LiteralPath $obj
'OBJECT UTC='+$info.LastWriteTimeUtc.ToString('O')+' Length='+$info.Length
$symbols=@(& $llvm -t $obj | ForEach-Object {if($_ -match '\(sec\s+2\).* 0x[0-9a-f]+ (.+)$') {$Matches[1]}})
$relation=@($symbols | Where-Object {$_ -like '*World__ExecuteQueryAdmitted<*' -and $_ -like '*SingleExecution*' -and $_ -like '*ComponentPairsWithin_4<*' -and $_ -like '*DefaultContacts*' -and $_ -like '*WhereSelection*' -and $_ -like '*SpatialPairOutput*'})
$hand=@($symbols | Where-Object {$_ -like '*World__ExecuteQueryAdmitted<*' -and $_ -like '*HandwrittenDefaultPairs_PairExecution_1<*' -and $_ -like '*SpatialPairOutput*'})
'MATCHCOUNTS relation='+$relation.Count+' hand='+$hand.Count
$targets=@($relation)+@($hand)
$targets | ForEach-Object {'TARGET '+$_}
if($relation.Count -ne 1 -or $hand.Count -ne 1) {'STOP selection count';exit 2}
$dump=@(& $llvm -d -r --no-show-raw-insn ('--disassemble-symbols='+($targets -join ',')) $obj)
if($LASTEXITCODE -ne 0) {exit $LASTEXITCODE}
$dump
$functions=[System.Collections.Generic.List[object]]::new();$current=$null
foreach($line in $dump) {
 if($line -match '^([0-9a-f]{16}) <(.+)>:$') {
  $current=[pscustomobject]@{Start=[Convert]::ToInt64($Matches[1],16);Role=$(if($Matches[2] -match 'HandwrittenDefaultPairs') {'Hand'} else {'Relation'});Code=[System.Collections.Generic.List[object]]::new()};$functions.Add($current)
 } elseif($null -ne $current -and $line -match '^\s+([0-9a-f]{1,8}):\s+(\S.*)$') {$current.Code.Add([pscustomobject]@{Address=[Convert]::ToInt64($Matches[1],16);Text=$Matches[2]})}
}
foreach($f in $functions) {
 while($f.Code.Count -gt 0 -and $f.Code[$f.Code.Count-1].Text -match '^nop') {$f.Code.RemoveAt($f.Code.Count-1)}
 $end=$f.Code[$f.Code.Count-1].Address+1
 [pscustomobject]@{Role=$f.Role;Start=('0x{0:x}' -f $f.Start);EndExclusive=('0x{0:x}' -f $end);Bytes=$end-$f.Start;Instructions=$f.Code.Count-@($f.Code | Where-Object {$_.Text -eq 'lock'}).Count;CallSites=@($f.Code | Where-Object {$_.Text -match '^callq'}).Count} | ConvertTo-Json -Compress
 foreach($row in $f.Code | Select-Object -First 14) {('PROLOG '+$f.Role+' 0x{0:x} ' -f $row.Address)+$row.Text}
 foreach($row in $f.Code | Where-Object {$_.Text -match '^callq' -and $_.Text -match 'PairExecution|ComponentPairsWithin'}) {('HOTCALL '+$f.Role+' 0x{0:x} ' -f $row.Address)+$row.Text}
}
